import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (4, 6)])
def test_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_skips_lines_and_strips_fields():
    lines = ["", " \t", "  # comment", " a , 1 , 0 ", "b, 2 , ", "c,3,1"]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 3, "flagged": True},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,0,extra", "a,no,0"])
def test_parse_error_counts_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log([" # header", "a,1,1", "", bad])


def test_duplicate_id_keeps_last_input_record_then_sorts():
    events = parse_transcript_log(["a,9,1", "b,2,0", "z,1,1", "a,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_daily_counts_include_gaps_and_ignore_outside_events():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["a,1,1", "b,4,1", "c,5,0"]), "empty": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rates():
    groups = {"b": [{"flagged": True}], "empty": [], "c": [{"flagged": None}], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 5) == ["a", "b", "c"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("c", 0.0), ("empty", None)]


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1], 0), ([1, 0, 2, 2, -1, 3], 2)])
def test_streak_counts_only_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
